// Demonstrates atomic counter vs. racy counter using Worker Threads
// Run with: node --experimental-vm-modules lock-free-demo.js

const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

const ITERATIONS = 200_000;
const NUM_WORKERS = 4;

if (isMainThread) {
  // SharedArrayBuffer: slot 0 = atomic counter, slot 1 = racy counter
  const sab = new SharedArrayBuffer(8);
  const shared = new Int32Array(sab);

  const workers = Array.from({ length: NUM_WORKERS }, () =>
    new Promise((resolve, reject) => {
      const w = new Worker(__filename);
      w.once('online', () => w.postMessage(sab));
      w.on('message', resolve);
      w.on('error', reject);
    })
  );

  Promise.all(workers).then(() => {
    const expected = NUM_WORKERS * ITERATIONS;
    console.log(`Expected        : ${expected}`);
    console.log(`Atomic (slot 0) : ${shared[0]}  <- always correct`);
    console.log(`Racy   (slot 1) : ${shared[1]}  <- lost updates!`);
    // Racy will be LESS than expected: read-modify-write is not atomic,
    // so two threads can read the same value, both add 1, and write
    // back the same result — one increment is silently lost.
  });

} else {
  parentPort.once('message', (sab) => {
    const shared = new Int32Array(sab);
    for (let i = 0; i < ITERATIONS; i++) {
      // CORRECT: single atomic fetch-and-add (wait-free)
      Atomics.add(shared, 0, 1);

      // RACY: three separate steps — another thread can interleave between any two
      const old = Atomics.load(shared, 1); // read
      // <-- another thread may read the same 'old' value right here
      Atomics.store(shared, 1, old + 1);   // write: silently overwrites concurrent write
    }
    parentPort.postMessage('done');
  });
}

// CAS loop as lock-free building block
// Atomics.compareExchange is the direct JavaScript CAS

const sab = new SharedArrayBuffer(4);
const counter = new Int32Array(sab);
Atomics.store(counter, 0, 0);

/**
 * Lock-free increment by arbitrary delta using CAS loop.
 * This is lock-free (not wait-free) — retries on collision.
 * Compare to Atomics.add which IS wait-free (single instruction).
 */
function lockFreeAdd(arr, index, delta) {
  while (true) {
    const expected = Atomics.load(arr, index);   // Step 1: read current
    const desired  = expected + delta;            // Step 2: compute new
    // Step 3: CAS — only writes if arr[index] === expected
    const actual = Atomics.compareExchange(arr, index, expected, desired);
    if (actual === expected) {
      return desired; // swap succeeded
    }
    // actual !== expected: another thread modified arr[index]
    // 'actual' is the current value — we could use it as next expected
    // but the spec requires a fresh Atomics.load to get correct ordering
  }
}

// Version-stamped value in a 2-slot SharedArrayBuffer
// Slot 0 = value, slot 1 = version (prevents ABA)
const vab = new SharedArrayBuffer(8);
const stamped = new Int32Array(vab);
Atomics.store(stamped, 0, 100); // initial value
Atomics.store(stamped, 1, 0);   // initial version

function casWithVersionStamp(arr, expectedVal, expectedVer, newVal) {
  // Note: in real multi-core code, both reads must be a single atomic
  // 128-bit operation (CMPXCHG16B). This JS simulation is illustrative only.
  const curVal = Atomics.load(arr, 0);
  const curVer = Atomics.load(arr, 1);
  if (curVal === expectedVal && curVer === expectedVer) {
    // Would be a single 128-bit CAS in real hardware
    Atomics.store(arr, 0, newVal);
    Atomics.add(arr, 1, 1);  // bump version — ABA prevented
    return { success: true, version: curVer + 1 };
  }
  return { success: false, curVal, curVer };
}

console.log(casWithVersionStamp(stamped, 100, 0, 200));
// { success: true, version: 1 }
console.log(casWithVersionStamp(stamped, 100, 0, 300));
// { success: false, curVal: 200, curVer: 1 } — version mismatch catches ABA
